create or replace function public.business_create_location(p_business_id uuid,p_name text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.can_manage_business(p_business_id) then raise exception 'Business admin permission required'; end if; insert into locations(business_id,name,is_active,created_by) values(p_business_id,trim(p_name),true,auth.uid()) returning id into v_id; return v_id; end $$;
create or replace function public.business_create_promotion(p_business_id uuid,p_title text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.can_manage_business(p_business_id) then raise exception 'Business admin permission required'; end if; insert into promotions(business_id,title,active,created_at) values(p_business_id,trim(p_title),true,now()) returning id into v_id; return v_id; end $$;
create or replace function public.business_create_event(p_business_id uuid,p_title text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.can_manage_business(p_business_id) then raise exception 'Business admin permission required'; end if; insert into business_events(business_id,title,created_at) values(p_business_id,trim(p_title),now()) returning id into v_id; return v_id; end $$;
create or replace function public.business_create_qr(p_business_id uuid,p_location_id uuid,p_label text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.can_manage_business(p_business_id) then raise exception 'Business admin permission required'; end if; if not exists(select 1 from locations where id=p_location_id and business_id=p_business_id) then raise exception 'Location does not belong to business'; end if; insert into qr_codes(location_id,code,active,label,customization) values(p_location_id,encode(gen_random_bytes(12),'hex'),true,trim(p_label),'{}'::jsonb) returning id into v_id; return v_id; end $$;
create or replace function public.business_create_partner_program(p_business_id uuid,p_name text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.can_manage_business(p_business_id) then raise exception 'Business admin permission required'; end if; insert into partner_programs(business_id,name,enabled) values(p_business_id,trim(p_name),true) returning id into v_id; return v_id; end $$;
revoke all on function public.business_create_location(uuid,text),public.business_create_promotion(uuid,text),public.business_create_event(uuid,text),public.business_create_qr(uuid,uuid,text),public.business_create_partner_program(uuid,text) from public;
grant execute on function public.business_create_location(uuid,text),public.business_create_promotion(uuid,text),public.business_create_event(uuid,text),public.business_create_qr(uuid,uuid,text),public.business_create_partner_program(uuid,text) to authenticated;
